from lib import *
LES = [
L("sym", "E", "Odd, even and periodic functions", "ฟังก์ชันคี่ คู่ และเป็นคาบ",
 [T("<b>Theorem.</b> Let $f$ be continuous on $[-a,a]$. If $f$ is odd ($f(-x)=-f(x)$) then $\\displaystyle\\int_{-a}^{a}f=0$; if $f$ is even ($f(-x)=f(x)$) then $\\displaystyle\\int_{-a}^{a}f=2\\int_{0}^{a}f$.",
    "<b>ทฤษฎีบท</b> ให้ $f$ ต่อเนื่องบน $[-a,a]$ ถ้า $f$ เป็นฟังก์ชันคี่ ($f(-x)=-f(x)$) แล้ว $\\displaystyle\\int_{-a}^{a}f=0$ ถ้า $f$ เป็นฟังก์ชันคู่ ($f(-x)=f(x)$) แล้ว $\\displaystyle\\int_{-a}^{a}f=2\\int_{0}^{a}f$"),
  T("<b>Theorem.</b> If $f$ is continuous on $\\mathbb{R}$ with period $T$, then $\\displaystyle\\int_{a}^{a+T}f=\\int_{0}^{T}f$ for every $a$, so $\\displaystyle\\int_{0}^{nT}f=n\\int_{0}^{T}f$.",
    "<b>ทฤษฎีบท</b> ถ้า $f$ ต่อเนื่องบน $\\mathbb{R}$ และมีคาบ $T$ แล้ว $\\displaystyle\\int_{a}^{a+T}f=\\int_{0}^{T}f$ ทุก $a$ ดังนั้น $\\displaystyle\\int_{0}^{nT}f=n\\int_{0}^{T}f$")],
 [S("Split at $0$ and substitute $x=-u$ in the left piece (lesson 9):", "แยกที่ $0$ แล้วแทน $x=-u$ ในส่วนซ้าย (บทที่ 9):", "\\int_{-a}^{0}f(x)\\,dx=\\int_{a}^{0}f(-u)(-du)=\\int_{0}^{a}f(-u)\\,du."),
  S("So", "ดังนั้น", "\\int_{-a}^{a}f=\\int_{0}^{a}\\big(f(-u)+f(u)\\big)\\,du,"),
  S("which is $0$ when $f$ is odd and $2\\int_{0}^{a}f$ when $f$ is even.", "ซึ่งเป็น $0$ เมื่อ $f$ คี่ และเป็น $2\\int_{0}^{a}f$ เมื่อ $f$ คู่"),
  S("Periodic: let $G(a)=\\int_{a}^{a+T}f$. By FTC (1) (lesson 4) and periodicity,", "เป็นคาบ: ให้ $G(a)=\\int_{a}^{a+T}f$ จาก FTC (1) (บทที่ 4) และความเป็นคาบ", "G'(a)=f(a+T)-f(a)=0,"),
  S("so $G$ is constant: $G(a)=G(0)=\\int_{0}^{T}f$. Splitting $[0,nT]$ into $n$ periods gives the last part. $\\blacksquare$", "$G$ จึงเป็นค่าคงตัว: $G(a)=G(0)=\\int_{0}^{T}f$ แยก $[0,nT]$ เป็น $n$ คาบได้ส่วนสุดท้าย $\\blacksquare$")],
 [X(r"\int_{-\pi}^{\pi}\left(x^{2}+\sin x\right)dx", "2pi^3/3", r"\frac{2\pi^{3}}{3}", "x**2+sin(x)", ("d", "-pi", "pi"), [r"\sin x\text{ is odd: }0", r"2\int_{0}^{\pi}x^{2}\,dx=\frac{2\pi^{3}}{3}"]),
  X(r"\int_{0}^{10\pi}|\sin x|\,dx", "20", r"20", "abs(sin(x))", ("d", "0", "10*pi", ["k*pi for k in range(1,10)"]), [r"|\sin x|\text{ has period }\pi", r"10\int_{0}^{\pi}\sin x\,dx=10\cdot2=20"])],
 [P(r"\int_{-2}^{2}\left(x^{3}-4x+1\right)dx", "4", r"4", "x**3-4*x+1", ("d", "-2", "2"), [r"x^{3}-4x\text{ is odd}", r"\int_{-2}^{2}1\,dx=4"], "Remove the odd part first.", "ตัดส่วนที่เป็นฟังก์ชันคี่ก่อน"),
  P(r"\int_{-1}^{1}\left(x^{2}+x^{5}e^{x^{2}}\right)dx", "2/3", r"\frac23", "x**2+x**5*exp(x**2)", ("d", "-1", "1"), [r"x^{5}e^{x^{2}}\text{ is odd}", r"2\int_{0}^{1}x^{2}\,dx=\frac23"], "$x^{5}$ is odd and $e^{x^{2}}$ is even: the product is odd.", "$x^{5}$ คี่ และ $e^{x^{2}}$ คู่ ผลคูณจึงคี่"),
  P(r"\int_{-\frac\pi4}^{\frac\pi4}\left(\sec^{2}x+x\tan^{2}x\right)dx", "2", r"2", "sec(x)**2+x*tan(x)**2", ("d", "-pi/4", "pi/4"), [r"x\tan^{2}x\text{ is odd}", r"\left[\tan x\right]_{-\frac\pi4}^{\frac\pi4}=1-(-1)=2"], "Is $x\\tan^{2}x$ odd or even?", "$x\\tan^{2}x$ เป็นคี่หรือคู่"),
  P(r"\int_{0}^{6\pi}|\cos x|\,dx", "12", r"12", "abs(cos(x))", ("d", "0", "6*pi", ["pi/2+k*pi for k in range(6)"]), [r"|\cos x|\text{ has period }\pi\text{ and }\int_{0}^{\pi}|\cos x|\,dx=2", r"6\cdot2=12"], "Period $\\pi$: find one period's integral.", "คาบ $\\pi$: หาอินทิกรัลหนึ่งคาบ"),
  P(r"\int_{0}^{4\pi}\sin^{2}x\,dx", "2pi", r"2\pi", "sin(x)**2", ("d", "0", "4*pi"), [r"\sin^{2}x\text{ has period }\pi,\ \int_{0}^{\pi}\sin^{2}x\,dx=\frac\pi2", r"4\cdot\frac\pi2=2\pi"], "$\\sin^{2}x$ has period $\\pi$.", "$\\sin^{2}x$ มีคาบ $\\pi$")]),

L("king", "E", "King's rule", "King's rule",
 [T("<b>Theorem (King's rule).</b> If $f$ is continuous on $[a,b]$, then $$\\int_{a}^{b}f(x)\\,dx=\\int_{a}^{b}f(a+b-x)\\,dx.$$",
    "<b>ทฤษฎีบท (King's rule)</b> ถ้า $f$ ต่อเนื่องบน $[a,b]$ แล้ว $$\\int_{a}^{b}f(x)\\,dx=\\int_{a}^{b}f(a+b-x)\\,dx$$"),
  T("<b>Corollaries.</b> (i) If $f(x)+f(a+b-x)=c$ (a constant), then $\\int_{a}^{b}f=\\frac{c(b-a)}{2}$. (ii) If $g(a+b-x)=g(x)$, then $\\int_{a}^{b}x\\,g(x)\\,dx=\\frac{a+b}{2}\\int_{a}^{b}g(x)\\,dx$.",
    "<b>บทแทรก</b> (i) ถ้า $f(x)+f(a+b-x)=c$ (ค่าคงตัว) แล้ว $\\int_{a}^{b}f=\\frac{c(b-a)}{2}$ (ii) ถ้า $g(a+b-x)=g(x)$ แล้ว $\\int_{a}^{b}x\\,g(x)\\,dx=\\frac{a+b}{2}\\int_{a}^{b}g(x)\\,dx$")],
 [S("Substitute $u=a+b-x$ (lesson 9): $du=-dx$, and $x=a\\mapsto u=b$, $x=b\\mapsto u=a$:", "แทน $u=a+b-x$ (บทที่ 9): $du=-dx$ และ $x=a\\mapsto u=b$, $x=b\\mapsto u=a$:", "\\int_{a}^{b}f(a+b-x)\\,dx=\\int_{b}^{a}f(u)\\,(-du)=\\int_{a}^{b}f(u)\\,du."),
  S("(i) Call the integral $I$. Adding the two forms of $I$:", "(i) ให้อินทิกรัลเป็น $I$ บวกสองรูปของ $I$:", "2I=\\int_{a}^{b}\\big(f(x)+f(a+b-x)\\big)\\,dx=c(b-a)."),
  S("(ii) Apply the rule to $x\\,g(x)$ and use $g(a+b-x)=g(x)$:", "(ii) ใช้กฎกับ $x\\,g(x)$ และ $g(a+b-x)=g(x)$:", "I=\\int_{a}^{b}(a+b-x)g(x)\\,dx\\ \\Rightarrow\\ 2I=(a+b)\\int_{a}^{b}g.\\ \\blacksquare")],
 [X(r"\int_{1}^{3}\frac{x^{2}}{x^{2}+(4-x)^{2}}\,dx", "1", r"1", "x**2/(x**2+(4-x)**2)", ("d", "1", "3"), [r"a+b=4:\ f(x)+f(4-x)=\frac{x^{2}+(4-x)^{2}}{x^{2}+(4-x)^{2}}=1", r"I=\frac{1\cdot(3-1)}{2}=1"]),
  X(r"\int_{0}^{\pi}x\sin x\,dx", "pi", r"\pi", "x*sin(x)", ("d", "0", "pi"), [r"g=\sin x,\ g(\pi-x)=g(x)", r"\frac\pi2\int_{0}^{\pi}\sin x\,dx=\frac\pi2\cdot2=\pi"])],
 [P(r"\int_{0}^{\frac\pi2}\frac{\cos^{3}x}{\sin^{3}x+\cos^{3}x}\,dx", "pi/4", r"\frac{\pi}{4}", "cos(x)**3/(sin(x)**3+cos(x)**3)", ("d", "0", "pi/2"), [r"x\to\tfrac\pi2-x\text{ swaps }\sin\text{ and }\cos", r"f(x)+f\left(\tfrac\pi2-x\right)=1\Rightarrow I=\frac\pi4"], "King's rule swaps $\\sin$ and $\\cos$ here.", "King's rule สลับ $\\sin$ กับ $\\cos$"),
  P(r"\int_{2}^{5}\frac{\sqrt x}{\sqrt x+\sqrt{7-x}}\,dx", "3/2", r"\frac32", "sqrt(x)/(sqrt(x)+sqrt(7-x))", ("d", "2", "5"), [r"a+b=7:\ f(x)+f(7-x)=1", r"I=\frac{5-2}{2}=\frac32"], "$a+b=7$.", "$a+b=7$"),
  P(r"\int_{0}^{\pi}x\sin^{2}x\,dx", "pi^2/4", r"\frac{\pi^{2}}{4}", "x*sin(x)**2", ("d", "0", "pi"), [r"g=\sin^{2}x\text{ is symmetric about }\tfrac\pi2", r"\frac\pi2\int_{0}^{\pi}\sin^{2}x\,dx=\frac\pi2\cdot\frac\pi2"], "Corollary (ii) with $g=\\sin^{2}x$.", "บทแทรก (ii) โดย $g=\\sin^{2}x$"),
  P(r"\int_{0}^{\frac\pi2}\ln(\tan x)\,dx", "0", r"0", "log(tan(x))", ("d", "0", "pi/2"), [r"\ln\tan\left(\tfrac\pi2-x\right)=\ln\cot x=-\ln\tan x", r"I=-I\Rightarrow I=0\ \text{(the integral converges)}"], "What is $\\tan\\left(\\frac\\pi2-x\\right)$?", "$\\tan\\left(\\frac\\pi2-x\\right)$ เท่ากับอะไร"),
  P(r"\int_{0}^{1}x(1-x)^{9}\,dx", "1/110", r"\frac{1}{110}", "x*(1-x)**9", ("d", "0", "1"), [r"x\to1-x:\ \int_{0}^{1}(1-x)x^{9}\,dx", r"=\frac{1}{10}-\frac{1}{11}=\frac{1}{110}"], "King's rule moves the power onto $x$.", "King's rule ย้ายเลขชี้กำลังมาที่ $x$")]),

L("esym", "E", "The 1/(1+eˣ) trick", "ทริค 1/(1+eˣ)",
 [T("<b>Theorem.</b> Let $f$ be continuous and even on $[-a,a]$, and $g$ continuous with $g>0$ and $g(-x)=\\dfrac{1}{g(x)}$. Then $$\\int_{-a}^{a}\\frac{f(x)}{1+g(x)}\\,dx=\\int_{0}^{a}f(x)\\,dx.$$",
    "<b>ทฤษฎีบท</b> ให้ $f$ ต่อเนื่องและเป็นฟังก์ชันคู่บน $[-a,a]$ และ $g$ ต่อเนื่อง $g>0$ และ $g(-x)=\\dfrac{1}{g(x)}$ แล้ว $$\\int_{-a}^{a}\\frac{f(x)}{1+g(x)}\\,dx=\\int_{0}^{a}f(x)\\,dx$$"),
  T("Typical $g$: $e^{x}$, $b^{x}$ ($b>0$), or $e^{h(x)}$ with $h$ odd, e.g. $e^{\\sin x}$.", "ตัวอย่าง $g$: $e^{x}$, $b^{x}$ ($b>0$) หรือ $e^{h(x)}$ ที่ $h$ เป็นฟังก์ชันคี่ เช่น $e^{\\sin x}$")],
 [S("Let $I$ be the integral. Substitute $x=-u$ (lesson 9) and use that $f$ is even:", "ให้ $I$ เป็นอินทิกรัล แทน $x=-u$ (บทที่ 9) และใช้ว่า $f$ เป็นฟังก์ชันคู่:", "I=\\int_{-a}^{a}\\frac{f(u)}{1+g(-u)}\\,du=\\int_{-a}^{a}\\frac{f(u)}{1+\\frac{1}{g(u)}}\\,du=\\int_{-a}^{a}\\frac{f(u)\\,g(u)}{g(u)+1}\\,du."),
  S("Add this to the original form of $I$:", "บวกกับรูปเดิมของ $I$:", "2I=\\int_{-a}^{a}f(u)\\,\\frac{1+g(u)}{1+g(u)}\\,du=\\int_{-a}^{a}f=2\\int_{0}^{a}f\\quad\\text{(lesson 17)}.\\ \\blacksquare")],
 [X(r"\int_{-1}^{1}\frac{x^{2}}{1+e^{x}}\,dx", "1/3", r"\frac13", "x**2/(1+exp(x))", ("d", "-1", "1"), [r"f=x^{2}\text{ even},\ g=e^{x}", r"\int_{0}^{1}x^{2}\,dx=\frac13"]),
  X(r"\int_{-\pi}^{\pi}\frac{\cos^{2}x}{1+2^{x}}\,dx", "pi/2", r"\frac{\pi}{2}", "cos(x)**2/(1+2**x)", ("d", "-pi", "pi"), [r"g=2^{x},\ 2^{-x}=\frac{1}{2^{x}}", r"\int_{0}^{\pi}\cos^{2}x\,dx=\frac\pi2"])],
 [P(r"\int_{-2}^{2}\frac{x^{4}}{1+e^{x}}\,dx", "32/5", r"\frac{32}{5}", "x**4/(1+exp(x))", ("d", "-2", "2"), [r"\int_{0}^{2}x^{4}\,dx=\frac{32}{5}"], "$f=x^{4}$ is even.", "$f=x^{4}$ เป็นฟังก์ชันคู่"),
  P(r"\int_{-\frac\pi2}^{\frac\pi2}\frac{\cos x}{1+e^{x}}\,dx", "1", r"1", "cos(x)/(1+exp(x))", ("d", "-pi/2", "pi/2"), [r"\int_{0}^{\frac\pi2}\cos x\,dx=1"], "$\\cos x$ is even.", "$\\cos x$ เป็นฟังก์ชันคู่"),
  P(r"\int_{-1}^{1}\frac{dx}{\left(1+e^{x}\right)\left(1+x^{2}\right)}", "pi/4", r"\frac{\pi}{4}", "1/((1+exp(x))*(1+x**2))", ("d", "-1", "1"), [r"f=\frac{1}{1+x^{2}}\text{ even}", r"\int_{0}^{1}\frac{dx}{1+x^{2}}=\frac\pi4"], "Take $f(x)=\\frac{1}{1+x^{2}}$.", "ให้ $f(x)=\\frac{1}{1+x^{2}}$"),
  P(r"\int_{-\pi}^{\pi}\frac{dx}{1+e^{\sin x}}", "pi", r"\pi", "1/(1+exp(sin(x)))", ("d", "-pi", "pi"), [r"g=e^{\sin x},\ g(-x)=e^{-\sin x}=\frac1{g(x)}", r"\int_{0}^{\pi}1\,dx=\pi"], "$\\sin x$ is odd, so $g=e^{\\sin x}$ works.", "$\\sin x$ เป็นฟังก์ชันคี่ $g=e^{\\sin x}$ จึงใช้ได้"),
  P(r"\int_{-3}^{3}\frac{x^{2}}{1+3^{x}}\,dx", "9", r"9", "x**2/(1+3**x)", ("d", "-3", "3"), [r"g=3^{x}:\ \int_{0}^{3}x^{2}\,dx=9"], "$g=3^{x}$.", "$g=3^{x}$")]),

L("recip", "E", "The substitution x → 1/x", "การแทน x → 1/x",
 [T("<b>Theorem.</b> Let $f$ be continuous on $(0,\\infty)$ and suppose $\\displaystyle\\int_{0}^{\\infty}f(x)\\,dx$ converges. Then $$\\int_{0}^{\\infty}f(x)\\,dx=\\int_{0}^{\\infty}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du.$$ Likewise, for $c>1$ and $f$ continuous on $\\left[\\frac1c,c\\right]$: $\\displaystyle\\int_{1/c}^{c}f(x)\\,dx=\\int_{1/c}^{c}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du$.",
    "<b>ทฤษฎีบท</b> ให้ $f$ ต่อเนื่องบน $(0,\\infty)$ และ $\\displaystyle\\int_{0}^{\\infty}f(x)\\,dx$ ลู่เข้า แล้ว $$\\int_{0}^{\\infty}f(x)\\,dx=\\int_{0}^{\\infty}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du$$ ในทำนองเดียวกัน สำหรับ $c>1$ และ $f$ ต่อเนื่องบน $\\left[\\frac1c,c\\right]$: $\\displaystyle\\int_{1/c}^{c}f(x)\\,dx=\\int_{1/c}^{c}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du$"),
  T("Use: if the new integrand is $-f$, then $I=0$; otherwise add the two forms, $2I=\\int\\left(f(x)+\\frac{f(1/x)}{x^{2}}\\right)dx$.", "การใช้: ถ้าฟังก์ชันใหม่เป็น $-f$ แล้ว $I=0$ มิฉะนั้นบวกสองรูป $2I=\\int\\left(f(x)+\\frac{f(1/x)}{x^{2}}\\right)dx$")],
 [S("By definition of the improper integral,", "จากนิยามของอินทิกรัลไม่ตรงแบบ", "\\int_{0}^{\\infty}f=\\lim_{\\varepsilon\\to0^{+},\\,R\\to\\infty}\\int_{\\varepsilon}^{R}f(x)\\,dx."),
  S("On $[\\varepsilon,R]$ with $0<\\varepsilon<R$, substitute $x=\\frac1u$, a $C^{1}$ bijection from $\\left[\\frac1R,\\frac1\\varepsilon\\right]$, $dx=-\\frac{du}{u^{2}}$:", "บน $[\\varepsilon,R]$ โดย $0<\\varepsilon<R$ แทน $x=\\frac1u$ ซึ่งเป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึงจาก $\\left[\\frac1R,\\frac1\\varepsilon\\right]$ และ $dx=-\\frac{du}{u^{2}}$:", "\\int_{\\varepsilon}^{R}f(x)\\,dx=\\int_{1/\\varepsilon}^{1/R}f\\left(\\tfrac1u\\right)\\left(-\\frac{du}{u^{2}}\\right)=\\int_{1/R}^{1/\\varepsilon}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du."),
  S("As $\\varepsilon\\to0^{+}$ and $R\\to\\infty$, the left side converges by assumption; the right side is the same number, and its limits $\\frac1R\\to0^{+}$, $\\frac1\\varepsilon\\to\\infty$. So the right improper integral converges to the same value.", "เมื่อ $\\varepsilon\\to0^{+}$ และ $R\\to\\infty$ ด้านซ้ายลู่เข้าตามสมมติฐาน ด้านขวาเป็นจำนวนเดียวกัน และขอบเขต $\\frac1R\\to0^{+}$, $\\frac1\\varepsilon\\to\\infty$ อินทิกรัลด้านขวาจึงลู่เข้าค่าเดียวกัน"),
  S("For $\\left[\\frac1c,c\\right]$ the same substitution maps the interval onto itself (no limits needed). $\\blacksquare$", "สำหรับ $\\left[\\frac1c,c\\right]$ การแทนเดียวกันส่งช่วงไปยังตัวเอง (ไม่ต้องใช้ลิมิต) $\\blacksquare$")],
 [X(r"\int_{0}^{\infty}\frac{dx}{\left(1+x^{2}\right)\left(1+x^{3}\right)}", "pi/4", r"\frac{\pi}{4}", "1/((1+x**2)*(1+x**3))", ("d", "0", "inf"), [r"x\to\tfrac1u:\ I=\int_{0}^{\infty}\frac{u^{3}\,du}{\left(1+u^{2}\right)\left(1+u^{3}\right)}", r"2I=\int_{0}^{\infty}\frac{1+u^{3}}{\left(1+u^{2}\right)\left(1+u^{3}\right)}du=\frac\pi2", r"I=\frac\pi4"]),
  X(r"\int_{\frac13}^{3}\frac{\arctan x}{x}\,dx", "pi/2*ln(3)", r"\frac\pi2\ln3", "atan(x)/x", ("d", "1/3", "3"), [r"x\to\tfrac1u:\ I=\int_{1/3}^{3}\frac{\arctan\frac1u}{u}\,du", r"\arctan x+\arctan\tfrac1x=\tfrac\pi2\ (x>0):\ 2I=\frac\pi2\int_{1/3}^{3}\frac{dx}{x}=\frac\pi2\ln9", r"I=\frac\pi2\ln3"])],
 [P(r"\int_{0}^{\infty}\frac{dx}{\left(1+x^{2}\right)\left(1+x^{10}\right)}", "pi/4", r"\frac{\pi}{4}", "1/((1+x**2)*(1+x**10))", ("d", "0", "inf"), [r"x\to\tfrac1u\text{ gives }\frac{u^{10}}{\left(1+u^{2}\right)\left(1+u^{10}\right)}", r"2I=\int_{0}^{\infty}\frac{dx}{1+x^{2}}=\frac\pi2"], "Same trick as the first example: the power doesn't matter.", "ทริคเดียวกับตัวอย่างแรก เลขชี้กำลังไม่สำคัญ"),
  P(r"\int_{0}^{\infty}\frac{\ln x}{(1+x)^{2}}\,dx", "0", r"0", "log(x)/(1+x)**2", ("d", "0", "inf"), [r"x\to\tfrac1u:\ \frac{\ln\frac1u}{\left(1+\frac1u\right)^{2}u^{2}}=-\frac{\ln u}{(u+1)^{2}}", r"I=-I\Rightarrow I=0"], "Simplify $\\frac{f(1/u)}{u^{2}}$.", "จัดรูป $\\frac{f(1/u)}{u^{2}}$"),
  P(r"\int_{0}^{\infty}\frac{1+x^{2}}{1+x^{4}}\,dx", "pi/sqrt(2)", r"\frac{\pi}{\sqrt2}", "(1+x**2)/(1+x**4)", ("d", "0", "inf"), [r"\text{Divide by }x^{2}:\ \frac{1+\frac{1}{x^{2}}}{\left(x-\frac1x\right)^{2}+2}", r"u=x-\tfrac1x\ (\text{maps }(0,\infty)\text{ onto }\mathbb{R}):\ \int_{-\infty}^{\infty}\frac{du}{u^{2}+2}=\frac{\pi}{\sqrt2}"], "Divide top and bottom by $x^{2}$, then $u=x-\\frac1x$.", "หารบนล่างด้วย $x^{2}$ แล้วให้ $u=x-\\frac1x$"),
  P(r"\int_{\frac12}^{2}\frac{\ln x}{1+x^{2}}\,dx", "0", r"0", "log(x)/(1+x**2)", ("d", "1/2", "2"), [r"x\to\tfrac1u\text{ maps }\left[\tfrac12,2\right]\text{ to itself and gives }-\frac{\ln u}{1+u^{2}}", r"I=-I\Rightarrow I=0"], "The interval $\\left[\\frac12,2\\right]$ is of the form $\\left[\\frac1c,c\\right]$.", "ช่วง $\\left[\\frac12,2\\right]$ อยู่ในรูป $\\left[\\frac1c,c\\right]$"),
  P(r"\int_{\frac12}^{2}\frac{\arctan x}{x}\,dx", "pi/2*ln(2)", r"\frac\pi2\ln2", "atan(x)/x", ("d", "1/2", "2"), [r"2I=\frac\pi2\int_{1/2}^{2}\frac{dx}{x}=\frac\pi2\ln4", r"I=\frac\pi2\ln2"], "Like the second example, with $c=2$.", "เหมือนตัวอย่างที่สอง โดย $c=2$")]),

L("weier", "E", "The Weierstrass substitution", "การแทนค่าแบบไวแยร์สตราส",
 [T("<b>Theorem.</b> On $(-\\pi,\\pi)$ the substitution $t=\\tan\\frac x2$ is a $C^{1}$ bijection onto $\\mathbb{R}$, and $$\\sin x=\\frac{2t}{1+t^{2}},\\qquad \\cos x=\\frac{1-t^{2}}{1+t^{2}},\\qquad dx=\\frac{2\\,dt}{1+t^{2}}.$$ So every integral of a rational function of $\\sin x$ and $\\cos x$ becomes the integral of a rational function of $t$ (then lesson 11).",
    "<b>ทฤษฎีบท</b> บน $(-\\pi,\\pi)$ การแทน $t=\\tan\\frac x2$ เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง $\\mathbb{R}$ และ $$\\sin x=\\frac{2t}{1+t^{2}},\\qquad \\cos x=\\frac{1-t^{2}}{1+t^{2}},\\qquad dx=\\frac{2\\,dt}{1+t^{2}}$$ ดังนั้นอินทิกรัลของฟังก์ชันตรรกยะของ $\\sin x$ และ $\\cos x$ จะกลายเป็นอินทิกรัลของฟังก์ชันตรรกยะของ $t$ (แล้วใช้บทที่ 11)")],
 [S("For $x\\in(-\\pi,\\pi)$, $\\frac x2\\in\\left(-\\frac\\pi2,\\frac\\pi2\\right)$, where $\\tan$ is a strictly increasing $C^{1}$ bijection onto $\\mathbb{R}$; its inverse is $x=2\\arctan t$.", "เมื่อ $x\\in(-\\pi,\\pi)$ จะได้ $\\frac x2\\in\\left(-\\frac\\pi2,\\frac\\pi2\\right)$ ซึ่ง $\\tan$ เพิ่มแท้ เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง $\\mathbb{R}$ ตัวผกผันคือ $x=2\\arctan t$"),
  S("Double-angle formulas with $\\cos^{2}\\frac x2=\\frac{1}{\\sec^{2}\\frac x2}=\\frac{1}{1+t^{2}}$:", "สูตรมุมสองเท่ากับ $\\cos^{2}\\frac x2=\\frac{1}{\\sec^{2}\\frac x2}=\\frac{1}{1+t^{2}}$:", "\\sin x=2\\tan\\tfrac x2\\cos^{2}\\tfrac x2=\\frac{2t}{1+t^{2}},\\qquad \\cos x=\\cos^{2}\\tfrac x2\\left(1-\\tan^{2}\\tfrac x2\\right)=\\frac{1-t^{2}}{1+t^{2}}."),
  S("From $x=2\\arctan t$ (lesson 13): $\\dfrac{dx}{dt}=\\dfrac{2}{1+t^{2}}$. The inverse-substitution form of lesson 9 now applies. $\\blacksquare$", "จาก $x=2\\arctan t$ (บทที่ 13): $\\dfrac{dx}{dt}=\\dfrac{2}{1+t^{2}}$ จึงใช้การแทนค่าผกผันของบทที่ 9 ได้ $\\blacksquare$")],
 [X(r"\int_{0}^{\frac\pi2}\frac{dx}{1+\sin x}", "1", r"1", "1/(1+sin(x))", ("d", "0", "pi/2"), [r"1+\sin x=\frac{(1+t)^{2}}{1+t^{2}},\ t:0\to1", r"\int_{0}^{1}\frac{2\,dt}{(1+t)^{2}}=\left[-\frac{2}{1+t}\right]_{0}^{1}=1"]),
  X(r"\int_{0}^{\frac\pi2}\frac{dx}{2+\cos x}", "pi/(3sqrt(3))", r"\frac{\pi}{3\sqrt3}", "1/(2+cos(x))", ("d", "0", "pi/2"), [r"2+\cos x=\frac{3+t^{2}}{1+t^{2}}", r"\int_{0}^{1}\frac{2\,dt}{3+t^{2}}=\frac{2}{\sqrt3}\arctan\frac{1}{\sqrt3}=\frac{\pi}{3\sqrt3}"])],
 [P(r"\int_{0}^{\frac\pi2}\frac{dx}{1+\cos x}", "1", r"1", "1/(1+cos(x))", ("d", "0", "pi/2"), [r"1+\cos x=\frac{2}{1+t^{2}}", r"\int_{0}^{1}dt=1"], "$1+\\cos x$ simplifies to $\\frac{2}{1+t^{2}}$.", "$1+\\cos x$ ลดรูปเป็น $\\frac{2}{1+t^{2}}$"),
  P(r"\int_{0}^{\frac\pi2}\frac{dx}{1+\sin x+\cos x}", "ln(2)", r"\ln2", "1/(1+sin(x)+cos(x))", ("d", "0", "pi/2"), [r"1+\sin x+\cos x=\frac{2+2t}{1+t^{2}}", r"\int_{0}^{1}\frac{dt}{1+t}=\ln2"], "Put everything over $1+t^{2}$.", "ทำทุกพจน์ให้มีส่วน $1+t^{2}$"),
  P(r"\int_{0}^{\frac\pi2}\frac{dx}{3+5\cos x}", "ln(3)/4", r"\frac{\ln3}{4}", "1/(3+5*cos(x))", ("d", "0", "pi/2"), [r"3+5\cos x=\frac{8-2t^{2}}{1+t^{2}}", r"\int_{0}^{1}\frac{dt}{4-t^{2}}=\left[\tfrac14\ln\frac{2+t}{2-t}\right]_{0}^{1}=\frac{\ln3}{4}"], "You get $\\int\\frac{dt}{4-t^{2}}$: partial fractions.", "ได้ $\\int\\frac{dt}{4-t^{2}}$ ใช้เศษส่วนย่อย"),
  P(r"\int_{0}^{\pi}\frac{dx}{2+\cos x}", "pi/sqrt(3)", r"\frac{\pi}{\sqrt3}", "1/(2+cos(x))", ("d", "0", "pi"), [r"t:0\to\infty\ \text{(an improper limit)}", r"\int_{0}^{\infty}\frac{2\,dt}{3+t^{2}}=\frac{2}{\sqrt3}\cdot\frac\pi2=\frac{\pi}{\sqrt3}"], "As $x\\to\\pi^{-}$, $t\\to\\infty$.", "เมื่อ $x\\to\\pi^{-}$ จะได้ $t\\to\\infty$"),
  P(r"\int_{0}^{\frac\pi2}\frac{dx}{5+4\sin x}", "2/3*arctan(1/3)", r"\frac23\arctan\frac13", "1/(5+4*sin(x))", ("d", "0", "pi/2"), [r"5+4\sin x=\frac{5t^{2}+8t+5}{1+t^{2}}", r"\int_{0}^{1}\frac{2\,dt}{5t^{2}+8t+5}=\frac23\left[\arctan\frac{5t+4}{3}\right]_{0}^{1}", r"=\frac23\left(\arctan3-\arctan\tfrac43\right)=\frac23\arctan\frac13"], "Complete the square in $5t^{2}+8t+5$.", "ทำกำลังสองสมบูรณ์ใน $5t^{2}+8t+5$")]),
]
